style.css:
@media (max-width: 1200px) and (min-width: 1100px) {
  #page-manager {
    margin-top: 0 !important;
    position: relative !important;
    z-index: 3000 !important;
  }
  
  #guide {
    z-index: 3010 !important;
  }
  
  .ytd-app .ytd-popup-container {
    z-index: 3010 !important;
  }
  
  #ytd-miniplayer {
    z-index: 3020 !important;
  }
  
  ytd-watch-flexy[full-bleed-player] #full-bleed-container.ytd-watch-flexy {
    height: 650px !important;  
    min-height: 650px !important;
  }

  ytd-watch-flexy[full-bleed-player] #ytd-player {
    height: 650px !important;  
  }

  ytd-watch-flexy[full-bleed-player] .html5-video-container .html5-main-video {
    height: 650px !important;
    width: 100% !important;
    left: 0px !important;
  }

  ytd-watch-flexy[full-bleed-player] #columns {
    display: none !important;
  }
}
